48		var findRoot func(string) string
49		findRoot = func(id string) string {
50			p, ok := parent[id]
51			if !ok {
52				parent[id] = id
53				return id
54			}
55			if p != id {
56				parent[id] = findRoot(p)
57			}
58			return parent[id]
59		}
60		union := func(a, b string) {
61			ra, rb := findRoot(a), findRoot(b)
62			if ra == rb {
63				return
64			}
65			if ra < rb {
66				parent[rb] = ra
67			} else {
68				parent[ra] = rb
69			}
70		}
