75				continue
76			}
77			if proposal.CandidateID == proposal.TargetID {
78				continue
79			}
80			if _, ok := active[proposal.CandidateID]; !ok {
81				continue
82			}
83			if _, ok := active[proposal.TargetID]; !ok {
84				continue
85			}
86			key := factProposalIdentityKey(proposal)
87			if prior, ok := validByIdentity[key]; !ok || proposal.Confidence > prior.Confidence {
88				validByIdentity[key] = proposal
89			}
90			union(proposal.CandidateID, proposal.TargetID)
91		}
92		valid := make([]factProposal, 0, len(validByIdentity))
93		for _, proposal := range validByIdentity {
94			valid = append(valid, proposal)
95		}
96		if len(valid) == 0 {
97			return nil
98		}
99	
100		idsByRoot := make(map[string][]string)
101		for id := range parent {
102			root := findRoot(id)
103			idsByRoot[root] = append(idsByRoot[root], id)
104		}
105		proposalsByRoot := make(map[string][]factProposal)
106		for _, proposal := range valid {
