	})
	for i := 0; i < 2; i++ {
		if !got[i].VerificationRequired || !hasRetrievalCaveat(got[i], retrievalCaveatCurrentCodeUnavailable) {
			t.Fatalf("memory result %d was not caveated: %+v", i, got[i])
		}
	}
	for i := 2; i < len(got); i++ {
