from __future__ import annotations

import json
import sys
from pathlib import Path

import pytest

TOOLS = Path(__file__).resolve().parent
sys.path.insert(0, str(TOOLS))

import analyze_sem_v7_design as design


def capacity_document() -> tuple[dict, str]:
    path = design.repository_path(design.CAPACITY_PATH)
    return design.holdout.load_json_with_sha256(path)


def test_anonymous_capacity_and_retention_parsing():
    capacity, _digest = capacity_document()

    counts = design.anonymous_language_counts(capacity)
    rates = design.anonymous_retention_rates(capacity)

    assert counts == [213, 147, 121, 103, 39, 1]
    assert len(rates) == 7
    assert all(0 <= rate <= 1 for rate in rates)


def test_simulation_is_deterministic(monkeypatch):
    monkeypatch.setattr(design, "SIMULATION_REPETITIONS", 100)
    arguments = (24, [100] * 5, [0.8], 10, 100)

    assert design.simulate_cap(*arguments) == design.simulate_cap(*arguments)


def test_large_repository_feasibility_respects_language_caps_and_minimums():
    assert design.maximum_selectable_large_repositories(
        [20, 20, 20, 20, 20], [20, 0, 0, 0, 0]
    ) == 8
    assert design.maximum_selectable_large_repositories(
        [20, 20, 20, 20, 20], [6, 6, 6, 6, 6]
    ) == 30
    assert design.maximum_selectable_large_repositories(
        [3, 20, 20, 20, 20], [3, 20, 20, 20, 20]
    ) is None
    assert design.maximum_selectable_large_repositories(
        [8, 8, 8, 8, 8], [8, 8, 8, 8, 0]
    ) == 26


@pytest.mark.parametrize(
    ("retained", "large"),
    [
        ([8] * 4, [8] * 4),
        ([8] * 5, [8] * 4 + [-1]),
        ([8] * 5, [8] * 4 + [True]),
        ([8] * 5, [8] * 4 + [9]),
    ],
)
def test_large_repository_feasibility_rejects_malformed_counts(retained, large):
    with pytest.raises(ValueError, match="selection counts are malformed"):
        design.maximum_selectable_large_repositories(retained, large)


@pytest.mark.parametrize(
    "arguments",
    [
        (25, [100] * 5, [0.8], 10, 100),
        (24, [100] * 4, [0.8], 10, 100),
        (24, [23] + [100] * 4, [0.8], 10, 100),
        (24, [100] * 5, [], 10, 100),
        (24, [100] * 5, [1.1], 10, 100),
        (24, [100] * 5, [0.8], 101, 100),
        (24, [100] * 5, [0.8], 0, 0),
    ],
)
def test_simulation_rejects_malformed_inputs(arguments):
    with pytest.raises(ValueError, match="simulation input is malformed"):
        design.simulate_cap(*arguments)


def test_selection_prefers_scale_strictness_then_smallest_cap():
    rows = []
    for cap in design.CANDIDATE_CAPS:
        rows.append(
            {
                "candidate_cap_per_language": cap,
                "candidate_repositories": cap * 5,
                "joint_pass_probability_by_large_repository_threshold": {
                    "10": 0.81 if cap >= 32 else 0.1,
                    "8": 0.95,
                    "6": 0.99,
                },
            }
        )

    selected = design.choose_design(rows)

    assert selected["minimum_large_repositories"] == 10
    assert selected["candidate_cap_per_language"] == 32


def test_selection_refuses_when_no_design_passes():
    rows = [
        {
            "candidate_cap_per_language": cap,
            "candidate_repositories": cap * 5,
            "joint_pass_probability_by_large_repository_threshold": {
                str(threshold): 0.1
                for threshold in design.LARGE_REPOSITORY_THRESHOLDS
            },
        }
        for cap in design.CANDIDATE_CAPS
    ]
    assert design.choose_design(rows) is None


def test_selection_rejects_missing_candidate_cap():
    rows = [
        {
            "candidate_cap_per_language": cap,
            "candidate_repositories": cap * 5,
            "joint_pass_probability_by_large_repository_threshold": {
                str(threshold): 1.0
                for threshold in design.LARGE_REPOSITORY_THRESHOLDS
            },
        }
        for cap in design.CANDIDATE_CAPS[:-1]
    ]
    with pytest.raises(ValueError, match="does not cover every candidate cap"):
        design.choose_design(rows)


@pytest.mark.parametrize(
    ("field", "value"),
    [
        (
            "eligible_repository_count_per_language_histogram",
            {"0": 1},
        ),
        (
            "eligible_repository_count_per_language_histogram",
            {"10": True},
        ),
    ],
)
def test_language_count_parser_rejects_malformed_histogram(field, value):
    capacity, _digest = capacity_document()
    capacity = json.loads(json.dumps(capacity))
    capacity["capacity"][field] = value
    with pytest.raises(ValueError, match="language capacity is malformed"):
        design.anonymous_language_counts(capacity)


@pytest.mark.parametrize("histogram", [{"2:3": 1}, {"2:1": True}])
def test_retention_parser_rejects_malformed_histogram(histogram):
    capacity, _digest = capacity_document()
    capacity = json.loads(json.dumps(capacity))
    capacity["historical_snapshot_screen"][
        "anonymous_language_candidate_and_eligible_count_histogram"
    ] = histogram
    with pytest.raises(ValueError, match="retention histogram is malformed"):
        design.anonymous_retention_rates(capacity)


def test_design_document_rejects_capacity_hash_mismatch(monkeypatch):
    capacity, _digest = capacity_document()
    monkeypatch.setattr(design, "SIMULATION_REPETITIONS", 10)

    with pytest.raises(ValueError, match="capacity boundary mismatch"):
        design.design_document(capacity, "0" * 64)


def test_design_document_rejects_weakened_identity_boundary(monkeypatch):
    capacity, digest = capacity_document()
    capacity = json.loads(json.dumps(capacity))
    capacity["analysis_boundary"]["queries_emitted"] = True
    monkeypatch.setattr(design, "SIMULATION_REPETITIONS", 10)

    with pytest.raises(ValueError, match="capacity boundary mismatch"):
        design.design_document(capacity, digest)


@pytest.mark.parametrize(
    ("field", "value"),
    [
        ("eligible_large_repositories_at_1000_files", True),
        ("eligible_repositories", False),
    ],
)
def test_design_document_rejects_boolean_scale_counts(monkeypatch, field, value):
    capacity, digest = capacity_document()
    capacity = json.loads(json.dumps(capacity))
    capacity["historical_snapshot_screen"][field] = value
    monkeypatch.setattr(design, "SIMULATION_REPETITIONS", 10)

    with pytest.raises(ValueError, match="scale evidence is malformed"):
        design.design_document(capacity, digest)


def test_design_document_contains_no_identity_shaped_values(monkeypatch):
    capacity, digest = capacity_document()
    monkeypatch.setattr(design, "SIMULATION_REPETITIONS", 100)

    document = design.design_document(capacity, digest)
    serialized = json.dumps(document)

    assert document["rank_production_authorized"] is False
    assert "/" not in serialized
    assert "sr6-" not in serialized


def test_committed_design_artifact_is_bound_and_authorizes_exact_design():
    path = design.repository_path(design.OUTPUT_PATH)
    document, digest = design.holdout.load_json_with_sha256(path)

    assert digest == (
        "210495841f91811a3dc970bfbe2fa9166269a6ab64d9078e606ebb7c9af5da7e"
    )
    assert document["inputs"]["analyzer_sha256"] == design.holdout.sha256_file(
        Path(design.__file__).resolve()
    )
    assert document["candidate_construction_authorized"] is True
    assert document["rank_production_authorized"] is False
    assert document["selected_design"] == {
        "candidate_cap_per_language": 36,
        "candidate_repositories": 180,
        "minimum_large_repositories": 10,
        "predicted_joint_feasibility": 0.8212,
    }
    serialized = json.dumps(document)
    assert "/" not in serialized
    assert "sr6-" not in serialized

