func repoStorageKey(ctx context.Context, runner CommandRunner, configDir, repoDir string) (string, error) {
	if runner != nil {
		stdout, _, err := runner.Run(ctx, repoDir, "git", "remote", "get-url", "origin")
		if err == nil {
