        '"setup_replacements"',
        '"validation"',
    )
    if any(term in lower for term in scaffolding):
        return True
    if "validation:" in lower:
        return True
    if stripped.startswith("test $("):
        return True
    if stripped.startswith('{"timestamp"') or '"payload"' in stripped[:300]:
